        var ramBlocks = descriptor is IVic20RamConfiguration { RamBlocksOverride: { } overrideBlocks }
            ? overrideBlocks
            : Vic20MemoryLayout.ToBlocks(Vic20MemoryLayout.ParseBoardModel(profile?.BoardModel));
290→
